 const unavailable = { kind: 'rejected', reason: 'unavailable' };

+/** Temporary, source-bound diagnostic: preserves all original assertions. */
+function observeScrollTiming(profile: string) {
+  const mode = process.env.PUI_SCROLL_RAF_MODE ?? 'native';
+  const output = process.env.PUI_SCROLL_TRACE_FILE!;
+  const controlled = mode !== 'native';
+  const originalRequest = window.requestAnimationFrame.bind(window);
+  const originalCancel = window.cancelAnimationFrame.bind(window);
+  const pending = new Map<number, { callback: FrameRequestCallback; native?: number }>();
+  let next = 0, sequence = 0, phase = 'mount', surface: HTMLElement | undefined;
+  function event(kind: string, detail: Record<string, unknown> = {}) {
+    appendFileSync(output, JSON.stringify({ profile, mode, sequence: ++sequence,
+      time: performance.now(), kind, phase, offset: surface?.scrollTop,
+      pending: [...pending.keys()], ...detail }) + '\n');
+  }
+  function fire(id: number, time: number) {
+    const work = pending.get(id);
+    if (!work) return;
+    pending.delete(id);
+    const previous = phase;
+    phase = `raf:${id} during ${previous}`;
+    event('raf-fire', { id });
+    try { work.callback(time); } finally {
+      event('raf-return', { id });
+      phase = previous;
+    }
+  }
+  vi.spyOn(window, 'requestAnimationFrame').mockImplementation(callback => {
+    const id = ++next;
+    const work: { callback: FrameRequestCallback; native?: number } = { callback };
+    pending.set(id, work);
+    event('raf-schedule', { id, stack: new Error().stack });
+    if (!controlled) work.native = originalRequest(time => fire(id, time));
+    return id;
+  });
+  vi.spyOn(window, 'cancelAnimationFrame').mockImplementation(id => {
+    const work = pending.get(id);
+    event('raf-cancel', { id });
+    pending.delete(id);
+    if (work?.native !== undefined) originalCancel(work.native);
+  });
+  return {
+    mode,
+    attach(current: HTMLElement) {
+      surface = current;
+      let target: object | null = current;
+      let descriptor: PropertyDescriptor | undefined;
+      while (target && !descriptor) {
+        descriptor = Object.getOwnPropertyDescriptor(target, 'scrollTop');
+        target = Object.getPrototypeOf(target);
+      }
+      let saved = current.scrollTop;
+      event('observe-offset', { descriptor: descriptor?.get ? 'accessor' : 'data' });
+      Object.defineProperty(current, 'scrollTop', {
+        configurable: true,
+        enumerable: true,
+        get() { return descriptor?.get ? descriptor.get.call(current) : saved; },
+        set(value: number) {
+          const before = current.scrollTop;
+          if (descriptor?.set) descriptor.set.call(current, value); else saved = value;
+          event('scrollTop-write', { before, requested: value, after: current.scrollTop,
+            stack: new Error().stack });
+        },
+      });
+    },
+    phase(value: string) { phase = value; event('phase'); },
+    request<T>(name: string, callback: () => T): T {
+      phase = `${name}:synchronous`;
+      event('request-before', { name });
+      const result = callback();
+      event('request-return', { name, result });
+      phase = `${name}:act-await`;
+      return result;
+    },
+    after(name: string) { phase = `${name}:after-act`; event('act-return', { name }); },
+    flush(where: string) {
+      phase = where;
+      event('controlled-flush-start');
+      for (const id of [...pending.keys()]) fire(id, performance.now());
+      event('controlled-flush-end');
+    },
+  };
+}
